#include <stdio.h>
#include <string.h>

int main() {
  char plaintext[] = "Hello world";
  char ciphertext[20];
  int i;

  printf("Original string: %s\n", plaintext);

  // XOR each character with 127
  for (i = 0; i < strlen(plaintext); i++) {
    ciphertext[i] = plaintext[i] ^ 127;
  }
  ciphertext[i] = '\0';
  printf("After XOR with 127: %s\n", ciphertext);

  // AND each character with 127
  for (i = 0; i < strlen(plaintext); i++) {
    ciphertext[i] = plaintext[i] & 127;
  }
  ciphertext[i] = '\0';
  printf("After AND with 127: %s\n", ciphertext);

  return 0;
}

#include <ctype.h>
#include <stdio.h>
#include <string.h>

void encrypt(char *str, int shift) {
  for (int i = 0; i < strlen(str); i++) {
    if (isalpha(str[i])) {
      char base = isupper(str[i]) ? 'A' : 'a';
      str[i] = (str[i] - base + shift) % 26 + base;
    }
  }
}

void decrypt(char *str, int shift) {
  for (int i = 0; i < strlen(str); i++) {
    if (isalpha(str[i])) {
      char base = isupper(str[i]) ? 'A' : 'a';
      str[i] = (str[i] - base - shift + 26) % 26 + base;
    }
  }
}

int main() {
  char str[100];
  int shift;

  printf("Enter a string: ");
  fgets(str, sizeof(str), stdin);
  str[strcspn(str, "\n")] = '\0';

  printf("Enter shift value: ");
  scanf("%d", &shift);

  printf("Original string: %s\n", str);

  encrypt(str, shift);
  printf("Encrypted string: %s\n", str);

  decrypt(str, shift);
  printf("Decrypted string: %s\n", str);

  return 0;
}
